import SpotifyWebApi from 'spotify-web-api-js';

const spotifyApi = new SpotifyWebApi();

export const setAccessToken = (token) => {
  spotifyApi.setAccessToken(token); // Make sure this function correctly sets the token
};

export const searchTracks = async (query) => {
    try {
      console.log('Searching for tracks with query:', query); // Log the search query
      const response = await spotifyApi.searchTracks(query);
      console.log('Spotify API Response:', response); // Log the API response
      return response.tracks.items;
    } catch (error) {
      console.error('Error fetching tracks:', error); // Log any error that occurs
      return [];
    }
  };
